DELETE FROM REVIEW_REPORT
WHERE MEMBER_NO = #{memberNo}
   OR ADMIN_NO = #{memberNo}

DELETE FROM ORDER_ITEM
WHERE ORDER_NO IN (
    SELECT ORDER_NO FROM ORDERS WHERE MEMBER_NO = #{memberNo}
)

DELETE FROM CART_ITEM
WHERE CART_NO IN (
    SELECT CART_NO FROM CART WHERE MEMBER_NO = #{memberNo}
)

mapper.update:
UPDATE EVENT
SET STATUS = #{status}
WHERE EVENT_NO = #{eventNo}
  AND STATUS = 'WAITING'

UPDATE PRODUCT
SET STATUS = #{status}
WHERE PRODUCT_NO = #{productNo}

mapper.select:
SELECT STATUS
FROM PRODUCT
WHERE PRODUCT_NO = #{productNo}

SELECT COUNT(*)
FROM ORDER_ITEM
WHERE PRODUCT_NO = #{productNo}

mapper.delete:
DELETE FROM PRODUCT
WHERE PRODUCT_NO = #{productNo}
  AND STATUS = 'DELETE_REQUESTED'

