mapper.insert:
INSERT INTO CONTENT_PLATFORM (
    CONTENT_PLATFORM_NO, CONTENT_NO, PLATFORM_NO
) VALUES (
    SEQ_CONTENT_PLATFORM_NO.NEXTVAL, #{contentNo}, #{platformNo}
