INSERT INTO OTT_PLATFORM (
    PLATFORM_NO, PLATFORM_NAME, LOGO_IMAGE, SITE_URL, IS_ACTIVE
) VALUES (
    SEQ_OTT_PLATFORM_NO.NEXTVAL, #{platformName}, #{logoImage}, #{siteUrl}, #{isActive}
